static int type_has_replaced_module(jl_value_t *t)
{
    if (jl_is_datatype(t)) {
        jl_datatype_t *dt = (jl_datatype_t*)t;
        if (is_module_replaced(dt->name->module))
            return 1;
        int i;
        for(i=0; i < jl_nparams(dt); i++)
            if (type_has_replaced_module(jl_tparam(dt,i)))
                return 1;
    }
